import XCTest
@testable import Likerts
actor Adapter:OfflineSecureAdapter{nonisolated let protectionProfile="keychain_device_only_aes_gcm";var records:[Data]=[];func load()async->[Data]{records};func replace(_ values:[Data])async{records=values};func seal(_ clear:Data)async->Data{Data([42])+Data(clear.map{$0 ^ 91})+Data([24])};func open(_ sealed:Data)async throws->Data{guard sealed.first==42,sealed.last==24 else{throw NSError(domain:"auth",code:1)};return Data(sealed.dropFirst().dropLast().map{$0 ^ 91})};func corrupt()async{records[0][3] ^= 1};func contains(_ value:String)async->Bool{records.contains{String(data:$0,encoding:.utf8)?.contains(value)==true}}}
actor Counter{var count=0;func next()->Int{count+=1;return count}}
final class OfflineQueueTests:XCTestCase{func testEncryptedOldestFirstRetryTerminalAndQuarantine()async throws{let adapter=Adapter();let queue=try OfflineQueue(adapter:adapter);_ = try await queue.enqueue(collectionId:"a",submission:Data("{\"secret\":\"answer\"}".utf8),idempotencyKey:"one");_ = try await queue.enqueue(collectionId:"b",submission:Data("{}".utf8),idempotencyKey:"two");_ = try await queue.enqueue(collectionId:"c",submission:Data("{}".utf8),idempotencyKey:"three");let contains=await adapter.contains("answer");XCTAssertFalse(contains);let counter=Counter();let report=try await queue.flush(credential:{_ in "token"},send:{collectionId,_,_ in switch await counter.next(){case 1:return OfflineAttempt(status:503,retryAfterSeconds:30);case 2:return OfflineAttempt(status:403);default:return OfflineAttempt(status:200,responseId:"r",receiptCollectionId:collectionId,accepted:true)}});XCTAssertEqual(report.attempted,3,"attempted");XCTAssertEqual(report.accepted,1,"accepted");XCTAssertEqual(report.status.pending,1,"pending");XCTAssertEqual(report.status.blocked[.revoked],1,"revoked");await adapter.corrupt();let quarantined=try await queue.snapshot().quarantined;XCTAssertEqual(quarantined,1,"quarantined");let purged=try await queue.purgeQuarantined();XCTAssertEqual(purged,1,"purged");let finalStatus=try await queue.snapshot();XCTAssertEqual(finalStatus.quarantined,0,"final")}}
